FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Sensor de nivel componente A *)
    nivelB : BOOL; (* Sensor de nivel componente B *)
    nivelVacio : BOOL; (* Sensor de reactor vacio *)
    btnInicio : BOOL; (* Boton de inicio de receta *)
    btnAbort : BOOL; (* Boton de abortar receta *)
    temp : REAL; (* Temperatura del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Valvula componente A *)
    vB : BOOL; (* Valvula componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Valvula de descarga *)
    fase : INT; (* Fase actual de la receta (0 a 5) *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador de mezclado *)
    trigInicio : R_TRIG; (* Detector de flanco para inicio *)
    trigAbort : R_TRIG; (* Detector de flanco para abortar *)
END_VAR

(* Deteccion de flancos de los botones *)
trigInicio(CLK := btnInicio);
trigAbort(CLK := btnAbort);

(* Logica de aborto (activa en fases 1 a 5) *)
IF trigAbort.Q AND fase > 0 THEN
    IF NOT nivelVacio THEN
        fase := 5; (* Hay producto, pasar a descarga *)
    ELSE
        fase := 0; (* Vacio, ir a reposo *)
    END_IF;
END_IF;

(* Maquina de estados de la receta secuencial *)
CASE fase OF
    0: (* Fase 0: Reposo *)
        IF trigInicio.Q THEN
            fase := 1;
        END_IF;

    1: (* Fase 1: Dosificar A *)
        IF nivelA THEN
            fase := 2;
        END_IF;

    2: (* Fase 2: Dosificar B *)
        IF nivelB THEN
            fase := 3;
        END_IF;

    3: (* Fase 3: Calentar *)
        IF temp >= 60.0 THEN
            fase := 4;
        END_IF;

    4: (* Fase 4: Mezclar *)
        IF tMezcla.Q THEN
            fase := 5;
        END_IF;

    5: (* Fase 5: Descargar *)
        IF nivelVacio THEN
            fase := 0;
        END_IF;
END_CASE;

(* Control del temporizador de mezcla *)
tMezcla(IN := (fase = 4), PT := T#120S);

(* Control de salidas basado en la fase activa *)
vA := (fase = 1);
vB := (fase = 2);
calentador := (fase = 3);
mezclador := (fase = 4);
vDescarga := (fase = 5);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Sensor de nivel para componente A *)
    nivelB : BOOL; (* Sensor de nivel para componente B *)
    nivelVacio : BOOL; (* Sensor de nivel para tanque vacío *)
    btnInicio : BOOL; (* Botón de inicio de receta *)
    btnAbort : BOOL; (* Botón de aborto de receta *)
    temp : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula para componente A *)
    vB : BOOL; (* Válvula para componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual del proceso *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador para la fase de mezcla *)
    recetaEnCurso : BOOL; (* Indica si la receta está en curso *)
END_VAR

(* Inicialización de salidas y variables *)
vA := FALSE;
vB := FALSE;
calentador := FALSE;
mezclador := FALSE;
vDescarga := FALSE;

(* Control de fases del proceso por lotes *)
CASE fase OF
    0: (* Reposo *)
        IF btnInicio AND NOT recetaEnCurso THEN
            fase := 1; (* Iniciar receta desde reposo *)
            recetaEnCurso := TRUE;
        END_IF

    1: (* Fase 1: Dosificación de A *)
        vA := NOT nivelA;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF

    2: (* Fase 2: Dosificación de B *)
        vB := NOT nivelB;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF

    3: (* Fase 3: Calentamiento *)
        calentador := temp < 60.0;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF

    4: (* Fase 4: Mezcla *)
        mezclador := TRUE;
        tMezcla(IN := TRUE, PT := T#120S);
        IF tMezcla.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF

    5: (* Fase 5: Descarga *)
        vDescarga := NOT nivelVacio;
        IF nivelVacio THEN
            vDescarga := FALSE;
            fase := 0;
            recetaEnCurso := FALSE;
        END_IF
END_CASE

(* Manejo del botón de aborto *)
IF btnAbort THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;
    IF fase <> 0 THEN
        IF NOT nivelVacio THEN
            fase := 5; (* Ir a descarga si no está vacío *)
        ELSE
            fase := 0; (* Ir a reposo si ya está vacío *)
            recetaEnCurso := FALSE;
        END_IF
    END_IF
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL;       // Sensor de nivel para el componente A
    nivelB : BOOL;       // Sensor de nivel para el componente B
    nivelVacio : BOOL;   // Sensor de nivel para el estado vacío
    btnInicio : BOOL;    // Botón de inicio
    btnAbort : BOOL;     // Botón de aborto
    temp : REAL;         // Temperatura actual del reactor
END_VAR

VAR_OUTPUT
    vA : BOOL;           // Válvula para el componente A
    vB : BOOL;           // Válvula para el componente B
    calentador : BOOL;   // Calentador del reactor
    mezclador : BOOL;    // Mezclador del reactor
    vDescarga : BOOL;    // Válvula de descarga
    fase : INT;          // Fase actual del proceso
END_VAR

VAR
    timerMezcla : TON;   // Temporizador para la fase de mezcla
    mezclaTiempo : TIME := T#120S; // Tiempo de mezcla
    recetaEnCurso : BOOL; // Indica si la receta está en curso
END_VAR

// Inicialización
IF NOT recetaEnCurso THEN
    fase := 0;
END_IF

// Control de la receta
CASE fase OF
    0: // Reposo
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;
        IF btnInicio AND NOT recetaEnCurso THEN
            recetaEnCurso := TRUE;
            fase := 1;
        END_IF

    1: // Fase 1: Dosificación de A
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF

    2: // Fase 2: Dosificación de B
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF

    3: // Fase 3: Calentamiento
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF

    4: // Fase 4: Mezcla
        mezclador := TRUE;
        timerMezcla(IN := TRUE, PT := mezclaTiempo);
        IF timerMezcla.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF

    5: // Fase 5: Descarga
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            recetaEnCurso := FALSE;
            fase := 0;
        END_IF
END_CASE

// Manejo del botón de aborto
IF btnAbort AND recetaEnCurso THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;
    IF NOT nivelVacio THEN
        fase := 5; // Forzar descarga si no está vacío
    ELSE
        recetaEnCurso := FALSE;
        fase := 0; // Volver a reposo si ya está vacío
    END_IF
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Nivel del componente A *)
    nivelB : BOOL; (* Nivel del componente B *)
    nivelVacio : BOOL; (* Nivel vacío del reactor *)
    btnInicio : BOOL; (* Botón de inicio *)
    btnAbort : BOOL; (* Botón de aborto *)
    temp : REAL; (* Temperatura del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula del componente A *)
    vB : BOOL; (* Válvula del componente B *)
    calentador : BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual *)
END_VAR
VAR
    tMezclador : TP; (* Temporizador para el mezclador *)
    inicioPulsado : BOOL := FALSE; (* Bandera para detectar el pulso de inicio *)
    abortPulsado : BOOL := FALSE; (* Bandera para detectar el pulso de aborto *)
END_VAR

(* Control de inicio *)
IF btnInicio AND NOT inicioPulsado AND fase = 0 THEN
    inicioPulsado := TRUE;
    fase := 1;
ELSEIF NOT btnInicio THEN
    inicioPulsado := FALSE;
END_IF;

(* Control de aborto *)
IF btnAbort AND NOT abortPulsado THEN
    abortPulsado := TRUE;
    CASE fase OF
        1..4:
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        5:
            IF nivelVacio THEN
                fase := 0;
            END_IF;
    END_CASE;
ELSEIF NOT btnAbort THEN
    abortPulsado := FALSE;
END_IF;

(* Control de las fases *)
CASE fase OF
    1:
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF;
    2:
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF;
    3:
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF;
    4:
        mezclador := TRUE;
        tMezclador(IN := TRUE, PT := T#120S);
        IF tMezclador.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF;
    5:
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            fase := 0;
        END_IF;
    ELSE
        (* Reposo *)
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;
END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Sensor de nivel para componente A *)
    nivelB : BOOL; (* Sensor de nivel para componente B *)
    nivelVacio : BOOL; (* Sensor de nivel para tanque vacío *)
    btnInicio : BOOL; (* Botón de inicio de receta *)
    btnAbort : BOOL; (* Botón de aborto de receta *)
    temp : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula para componente A *)
    vB : BOOL; (* Válvula para componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual del proceso *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador para la fase de mezcla *)
    recetaEnCurso : BOOL; (* Indicador de receta en curso *)
END_VAR

(* Inicialización de salidas y variables *)
vA := FALSE;
vB := FALSE;
calentador := FALSE;
mezclador := FALSE;
vDescarga := FALSE;

(* Control de fases del proceso *)
IF NOT recetaEnCurso THEN
    IF btnInicio THEN
        recetaEnCurso := TRUE;
        fase := 1;
    ELSE
        fase := 0;
    END_IF;
ELSE
    CASE fase OF
        1: (* Fase 1: Dosificación de A *)
            vA := NOT nivelA;
            IF nivelA THEN
                vA := FALSE;
                fase := 2;
            END_IF;
        2: (* Fase 2: Dosificación de B *)
            vB := NOT nivelB;
            IF nivelB THEN
                vB := FALSE;
                fase := 3;
            END_IF;
        3: (* Fase 3: Calentamiento *)
            calentador := temp < 60.0;
            IF temp >= 60.0 THEN
                calentador := FALSE;
                fase := 4;
                tMezcla(IN := TRUE, PT := T#120S);
            END_IF;
        4: (* Fase 4: Mezcla *)
            mezclador := tMezcla.Q;
            IF tMezcla.Q THEN
                mezclador := FALSE;
                fase := 5;
            END_IF;
        5: (* Fase 5: Descarga *)
            vDescarga := NOT nivelVacio;
            IF nivelVacio THEN
                vDescarga := FALSE;
                recetaEnCurso := FALSE;
                fase := 0;
            END_IF;
    END_CASE;
END_IF;

(* Manejo de aborto *)
IF btnAbort AND recetaEnCurso THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;
    IF fase <> 5 THEN
        fase := 5;
    END_IF;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA    : BOOL;   (* Sensor nivel componente A alcanzado *)
    nivelB    : BOOL;   (* Sensor nivel componente B alcanzado *)
    nivelVacio: BOOL;   (* Sensor reactor vacío *)
    btnInicio : BOOL;   (* Botón inicio receta (flanco no requerido, nivel) *)
    btnAbort  : BOOL;   (* Botón abort *)
    temp      : REAL;   (* Temperatura actual del reactor *)
END_VAR

VAR_OUTPUT
    vA        : BOOL;   (* Válvula componente A *)
    vB        : BOOL;   (* Válvula componente B *)
    calentador: BOOL;   (* Calentador *)
    mezclador : BOOL;   (* Mezclador *)
    vDescarga : BOOL;   (* Válvula de descarga *)
    fase      : INT;    (* Fase activa: 0=reposo, 1-5=fases receta *)
END_VAR

VAR
    timerMezcla   : TON;            (* Temporizador fase 4 mezcla *)
    abortando     : BOOL;           (* Indica que se está ejecutando un abort *)
    btnInicio_prev: BOOL;           (* Valor anterior de btnInicio para flanco *)
    btnAbort_prev : BOOL;           (* Valor anterior de btnAbort para flanco *)
    btnInicio_re  : BOOL;           (* Flanco ascendente btnInicio *)
    btnAbort_re   : BOOL;           (* Flanco ascendente btnAbort *)
END_VAR

(* ─────────────────────────────────────────────
   Detección de flancos ascendentes
   ───────────────────────────────────────────── *)
btnInicio_re := btnInicio AND NOT btnInicio_prev;
btnAbort_re  := btnAbort  AND NOT btnAbort_prev;

(* ─────────────────────────────────────────────
   Lógica principal de fases
   ───────────────────────────────────────────── *)
CASE fase OF

    (* ── FASE 0: Reposo ── *)
    0:
        abortando := FALSE;

        (* Arranque solo desde reposo, con flanco de btnInicio *)
        IF btnInicio_re THEN
            fase := 1;
        END_IF;
        (* btnAbort en reposo no tiene efecto *)

    (* ── FASE 1: Dosificar componente A ── *)
    1:
        IF btnAbort_re THEN
            abortando := TRUE;
            (* Cerrar actuadores inmediatamente *)
            vA        := FALSE;
            vB        := FALSE;
            calentador:= FALSE;
            mezclador := FALSE;
            (* Decidir si hay que descargar *)
            IF NOT nivelVacio THEN
                fase := 5;  (* Hay producto: descargar *)
            ELSE
                fase := 0;  (* Reactor ya vacío: reposo *)
            END_IF;
        ELSIF nivelA THEN
            fase := 2;      (* Nivel A alcanzado: siguiente fase *)
        END_IF;

    (* ── FASE 2: Dosificar componente B ── *)
    2:
        IF btnAbort_re THEN
            abortando := TRUE;
            vA        := FALSE;
            vB        := FALSE;
            calentador:= FALSE;
            mezclador := FALSE;
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        ELSIF nivelB THEN
            fase := 3;      (* Nivel B alcanzado: siguiente fase *)
        END_IF;

    (* ── FASE 3: Calentar ── *)
    3:
        IF btnAbort_re THEN
            abortando := TRUE;
            vA        := FALSE;
            vB        := FALSE;
            calentador:= FALSE;
            mezclador := FALSE;
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        ELSIF temp >= 60.0 THEN
            fase := 4;      (* Temperatura alcanzada: siguiente fase *)
        END_IF;

    (* ── FASE 4: Mezclar 120 s ── *)
    4:
        IF btnAbort_re THEN
            abortando := TRUE;
            vA        := FALSE;
            vB        := FALSE;
            calentador:= FALSE;
            mezclador := FALSE;
            timerMezcla(IN := FALSE);  (* Resetear temporizador *)
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        ELSIF timerMezcla.Q THEN
            timerMezcla(IN := FALSE);  (* Resetear temporizador *)
            fase := 5;                 (* Tiempo cumplido: descargar *)
        END_IF;

    (* ── FASE 5: Descargar ── *)
    5:
        (* Un abort durante la descarga continúa la descarga;
           solo se marca abortando si aún no estaba activo *)
        IF btnAbort_re AND NOT abortando THEN
            abortando := TRUE;
            (* Los demás actuadores ya deben estar apagados,
               pero se asegura por si el abort ocurre en fase 5 normal *)
            vA        := FALSE;
            vB        := FALSE;
            calentador:= FALSE;
            mezclador := FALSE;
        END_IF;

        IF nivelVacio THEN
            fase := 0;      (* Reactor vacío: volver a reposo *)
        END_IF;

END_CASE;

(* ─────────────────────────────────────────────
   Asignación de salidas según fase activa
   ───────────────────────────────────────────── *)
CASE fase OF
    0:  (* Reposo: todo apagado *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        timerMezcla(IN := FALSE);

    1:  (* Dosificar A *)
        vA         := TRUE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        timerMezcla(IN := FALSE);

    2:  (* Dosificar B *)
        vA         := FALSE;
        vB         := TRUE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        timerMezcla(IN := FALSE);

    3:  (* Calentar *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := TRUE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        timerMezcla(IN := FALSE);

    4:  (* Mezclar *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := TRUE;
        vDescarga  := FALSE;
        timerMezcla(IN := TRUE, PT := T#120S);  (* Activar temporizador *)

    5:  (* Descargar *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := TRUE;
        timerMezcla(IN := FALSE);

END_CASE;

(* ─────────────────────────────────────────────
   Actualizar valores previos para próximo ciclo
   ───────────────────────────────────────────── *)
btnInicio_prev := btnInicio;
btnAbort_prev  := btnAbort;

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA, nivelB, nivelVacio, btnInicio, btnAbort : BOOL;
    temp : REAL;
END_VAR

VAR_OUTPUT
    vA, vB, calentador, mezclador, vDescarga : BOOL;
    fase : INT;
END_VAR

VAR
    timerMezclador : TON;
    estado : INT := 0; // 0: reposo, 1: dosificar A, 2: dosificar B, 3: calentar, 4: mezclar, 5: descargar
END_VAR

METHOD StartBatch : BOOL
VAR
    started : BOOL := FALSE;
END_VAR
    IF btnInicio AND estado = 0 THEN
        estado := 1;
        started := TRUE;
    END_IF
    StartBatch := started;
END_METHOD

METHOD AbortBatch : BOOL
VAR
    aborted : BOOL := FALSE;
END_VAR
    IF btnAbort AND estado > 0 THEN
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        IF NOT nivelVacio THEN
            estado := 5;
        ELSE
            estado := 0;
        END_IF
        aborted := TRUE;
    END_IF
    AbortBatch := aborted;
END_METHOD

METHOD UpdateBatch : BOOL
VAR
    updated : BOOL := FALSE;
END_VAR
    CASE estado OF
        0: // reposo
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 0;
        1: // dosificar A
            vA := TRUE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 1;
            IF nivelA THEN
                vA := FALSE;
                estado := 2;
            END_IF;
        2: // dosificar B
            vA := FALSE;
            vB := TRUE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 2;
            IF nivelB THEN
                vB := FALSE;
                estado := 3;
            END_IF;
        3: // calentar
            vA := FALSE;
            vB := FALSE;
            calentador := TRUE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 3;
            IF temp >= 60.0 THEN
                calentador := FALSE;
                estado := 4;
            END_IF;
        4: // mezclar
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := TRUE;
            vDescarga := FALSE;
            fase := 4;
            timerMezclador(IN := TRUE, PT := T#120S);
            IF timerMezclador.Q THEN
                mezclador := FALSE;
                estado := 5;
            END_IF;
        5: // descargar
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := TRUE;
            fase := 5;
            IF nivelVacio THEN
                vDescarga := FALSE;
                estado := 0;
            END_IF;
    END_CASE
    updated := TRUE;
    UpdateBatch := updated;
END_METHOD

METHOD Execute : BOOL
VAR
    executed : BOOL := FALSE;
END_VAR
    IF StartBatch() OR AbortBatch() OR UpdateBatch() THEN
        executed := TRUE;
    END_IF
    Execute := executed;
END_METHOD

// Main execution
Execute();

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Nivel del componente A *)
    nivelB : BOOL; (* Nivel del componente B *)
    nivelVacio : BOOL; (* Nivel vacío del reactor *)
    btnInicio : BOOL; (* Botón de inicio *)
    btnAbort : BOOL; (* Botón de abortar *)
    temp : REAL; (* Temperatura del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula del componente A *)
    vB : BOOL; (* Válvula del componente B *)
    calentador : BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual *)
END_VAR
VAR
    tMezclar : TP; (* Temporizador para mezclar *)
    inicioPulsado : BOOL := FALSE; (* Bandera para detectar pulsación de btnInicio *)
    abortPulsado : BOOL := FALSE; (* Bandera para detectar pulsación de btnAbort *)
END_VAR

(* Control de inicio *)
IF btnInicio AND NOT inicioPulsado AND fase = 0 THEN
    fase := 1;
    inicioPulsado := TRUE;
END_IF

(* Control de abort *)
IF btnAbort AND NOT abortPulsado THEN
    abortPulsado := TRUE;
    CASE fase OF
        1..4:
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        5:
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
    END_CASE;
END_IF

(* Control de las fases *)
CASE fase OF
    1:
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF;
    2:
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF;
    3:
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF;
    4:
        mezclador := TRUE;
        tMezclar(IN := TRUE, PT := T#120S);
        IF tMezclar.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF;
    5:
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            fase := 0;
        END_IF;
    0:
        (* Reposo *)
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;
        IF btnAbort THEN
            abortPulsado := TRUE;
        END_IF;
END_CASE

(* Reinicio de las banderas *)
IF NOT btnInicio THEN
    inicioPulsado := FALSE;
END_IF
IF NOT btnAbort THEN
    abortPulsado := FALSE;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA    : BOOL; (* Sensor nivel componente A alcanzado *)
    nivelB    : BOOL; (* Sensor nivel componente B alcanzado *)
    nivelVacio : BOOL; (* Sensor reactor vacio *)
    btnInicio : BOOL; (* Boton inicio receta *)
    btnAbort  : BOOL; (* Boton abortar receta *)
    temp      : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA        : BOOL; (* Valvula componente A *)
    vB        : BOOL; (* Valvula componente B *)
    calentador : BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Valvula de descarga *)
    fase      : INT;  (* Fase activa: 0=reposo, 1-5=receta *)
END_VAR
VAR
    tMezcla   : TON;  (* Temporizador mezcla 120 s *)
    abortado  : BOOL; (* Indica que se esta ejecutando un abort *)
END_VAR

(* ------------------------------------------------------------------ *)
(* Logica de abort: actua en fases 1 a 5                              *)
(* ------------------------------------------------------------------ *)
IF btnAbort AND (fase >= 1) AND (fase <= 5) THEN
    (* Apagar actuadores de proceso inmediatamente *)
    vA        := FALSE;
    vB        := FALSE;
    calentador := FALSE;
    mezclador := FALSE;

    IF fase <> 5 THEN
        (* Si hay producto en el reactor, ir a descarga *)
        IF NOT nivelVacio THEN
            abortado := TRUE;
            fase     := 5;
        ELSE
            (* Reactor ya vacio, volver a reposo *)
            abortado := FALSE;
            fase     := 0;
        END_IF;
    END_IF;
    (* Si ya estabamos en fase 5, continuar descarga normalmente *)
END_IF;

(* ------------------------------------------------------------------ *)
(* Maquina de estados secuencial                                       *)
(* ------------------------------------------------------------------ *)
CASE fase OF

    (* ---- FASE 0: Reposo ------------------------------------------ *)
    0:
        (* Asegurar todas las salidas apagadas *)
        vA        := FALSE;
        vB        := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;
        abortado  := FALSE;

        (* Arranque solo desde reposo *)
        IF btnInicio THEN
            fase := 1;
        END_IF;

    (* ---- FASE 1: Dosificar componente A --------------------------- *)
    1:
        vA        := TRUE;
        vB        := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF nivelA THEN
            vA   := FALSE;
            fase := 2;
        END_IF;

    (* ---- FASE 2: Dosificar componente B --------------------------- *)
    2:
        vA        := FALSE;
        vB        := TRUE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF nivelB THEN
            vB   := FALSE;
            fase := 3;
        END_IF;

    (* ---- FASE 3: Calentar hasta 60 grados ------------------------- *)
    3:
        vA        := FALSE;
        vB        := FALSE;
        calentador := TRUE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase       := 4;
        END_IF;

    (* ---- FASE 4: Mezclar 120 segundos ----------------------------- *)
    4:
        vA        := FALSE;
        vB        := FALSE;
        calentador := FALSE;
        mezclador := TRUE;
        vDescarga := FALSE;

        (* Temporizador activo mientras estemos en fase 4 *)
        tMezcla(IN := (fase = 4), PT := T#120S);

        IF tMezcla.Q THEN
            mezclador := FALSE;
            fase      := 5;
        END_IF;

    (* ---- FASE 5: Descargar hasta reactor vacio -------------------- *)
    5:
        vA        := FALSE;
        vB        := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := TRUE;

        IF nivelVacio THEN
            vDescarga := FALSE;
            abortado  := FALSE;
            fase      := 0;
        END_IF;

    (* ---- Estado no definido: volver a reposo ---------------------- *)
    ELSE
        fase := 0;

END_CASE;

(* Asegurar que el temporizador no quede activo fuera de fase 4 *)
IF fase <> 4 THEN
    tMezcla(IN := FALSE, PT := T#120S);
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch

VAR_INPUT
    nivelA    : BOOL;   (* Sensor nivel componente A alcanzado *)
    nivelB    : BOOL;   (* Sensor nivel componente B alcanzado *)
    nivelVacio : BOOL;  (* Sensor reactor vacío *)
    btnInicio : BOOL;   (* Botón inicio receta (flanco no requerido, nivel) *)
    btnAbort  : BOOL;   (* Botón abort *)
    temp      : REAL;   (* Temperatura actual del reactor *)
END_VAR

VAR_OUTPUT
    vA        : BOOL;   (* Válvula componente A *)
    vB        : BOOL;   (* Válvula componente B *)
    calentador : BOOL;  (* Calentador *)
    mezclador : BOOL;   (* Mezclador *)
    vDescarga : BOOL;   (* Válvula de descarga *)
    fase      : INT;    (* Fase activa: 0=reposo, 1-5=fases receta *)
END_VAR

VAR
    timerMezcla   : TON;        (* Temporizador fase 4 mezcla *)
    abortActivo   : BOOL;       (* Indica que se está ejecutando un abort *)
    btnInicioAnterior : BOOL;   (* Flanco ascendente btnInicio *)
    btnAbortAnterior  : BOOL;   (* Flanco ascendente btnAbort *)
    flancoInicio  : BOOL;       (* Flanco detectado btnInicio *)
    flancoAbort   : BOOL;       (* Flanco detectado btnAbort *)
END_VAR

(* ─── Detección de flancos ascendentes ─────────────────────────────────── *)
flancoInicio := btnInicio AND NOT btnInicioAnterior;
flancoAbort  := btnAbort  AND NOT btnAbortAnterior;

(* ─── Lógica principal por fase ─────────────────────────────────────────── *)

(* --- Gestión de ABORT (fases 1 a 5) ------------------------------------ *)
IF flancoAbort AND (fase >= 1) AND (fase <= 5) THEN
    abortActivo := TRUE;

    (* Apagar actuadores de proceso inmediatamente *)
    vA         := FALSE;
    vB         := FALSE;
    calentador := FALSE;
    mezclador  := FALSE;

    (* Decidir siguiente estado *)
    IF fase = 5 THEN
        (* Ya estamos descargando: continuar fase 5 sin cambio *)
        (* abortActivo queda TRUE para que al vaciar vuelva a reposo *)
        (* No se cambia fase *)
    ELSIF nivelVacio THEN
        (* Reactor ya vacío: ir directamente a reposo *)
        vDescarga  := FALSE;
        fase       := 0;
        abortActivo := FALSE;
    ELSE
        (* Hay producto: ir a fase 5 para descargar *)
        fase := 5;
    END_IF;
END_IF;

(* --- Máquina de estados ------------------------------------------------- *)
CASE fase OF

    (* ── FASE 0: Reposo ─────────────────────────────────────────────── *)
    0:
        (* Asegurar todas las salidas apagadas *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        abortActivo := FALSE;

        (* Arranque solo con flanco de btnInicio *)
        IF flancoInicio THEN
            fase := 1;
        END_IF;

    (* ── FASE 1: Dosificar componente A ─────────────────────────────── *)
    1:
        vA := TRUE;

        IF nivelA THEN
            vA   := FALSE;
            fase := 2;
        END_IF;

    (* ── FASE 2: Dosificar componente B ─────────────────────────────── *)
    2:
        vB := TRUE;

        IF nivelB THEN
            vB   := FALSE;
            fase := 3;
        END_IF;

    (* ── FASE 3: Calentar hasta 60 °C ───────────────────────────────── *)
    3:
        calentador := TRUE;

        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase       := 4;
            (* Reiniciar temporizador antes de entrar en fase 4 *)
            timerMezcla(IN := FALSE, PT := T#120S);
        END_IF;

    (* ── FASE 4: Mezclar 120 segundos ───────────────────────────────── *)
    4:
        mezclador := TRUE;
        timerMezcla(IN := TRUE, PT := T#120S);

        IF timerMezcla.Q THEN
            mezclador := FALSE;
            timerMezcla(IN := FALSE, PT := T#120S); (* Reset timer *)
            fase := 5;
        END_IF;

    (* ── FASE 5: Descargar hasta reactor vacío ──────────────────────── *)
    5:
        vDescarga := TRUE;

        IF nivelVacio THEN
            vDescarga   := FALSE;
            fase        := 0;
            abortActivo := FALSE;
        END_IF;

    (* ── Estado no definido: volver a reposo ────────────────────────── *)
    ELSE:
        fase := 0;

END_CASE;

(* ─── Actualizar memoria de flancos ─────────────────────────────────────── *)
btnInicioAnterior := btnInicio;
btnAbortAnterior  := btnAbort;

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Sensor de nivel para componente A *)
    nivelB : BOOL; (* Sensor de nivel para componente B *)
    nivelVacio : BOOL; (* Sensor de nivel vacío del reactor *)
    btnInicio : BOOL; (* Botón de inicio de la receta *)
    btnAbort : BOOL; (* Botón de aborto de la receta *)
    temp : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula para dosificar componente A *)
    vB : BOOL; (* Válvula para dosificar componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Válvula de descarga del reactor *)
    fase : INT; (* Fase actual del proceso *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador para la fase de mezcla *)
    recetaEnCurso : BOOL; (* Indica si la receta está en curso *)
END_VAR

(* Control de la receta por lotes *)
IF NOT recetaEnCurso THEN
    IF btnInicio AND (fase = 0) THEN
        recetaEnCurso := TRUE;
        fase := 1;
    END_IF;
ELSE
    CASE fase OF
        1: (* Fase 1: Dosificación de A *)
            vA := NOT nivelA;
            IF nivelA THEN
                vA := FALSE;
                fase := 2;
            END_IF;
        2: (* Fase 2: Dosificación de B *)
            vB := NOT nivelB;
            IF nivelB THEN
                vB := FALSE;
                fase := 3;
            END_IF;
        3: (* Fase 3: Calentamiento *)
            calentador := (temp < 60.0);
            IF temp >= 60.0 THEN
                calentador := FALSE;
                fase := 4;
                tMezcla(IN := TRUE, PT := T#120S);
            END_IF;
        4: (* Fase 4: Mezcla *)
            mezclador := tMezcla.Q;
            IF NOT tMezcla.Q THEN
                mezclador := FALSE;
                fase := 5;
            END_IF;
        5: (* Fase 5: Descarga *)
            vDescarga := NOT nivelVacio;
            IF nivelVacio THEN
                vDescarga := FALSE;
                recetaEnCurso := FALSE;
                fase := 0;
            END_IF;
    END_CASE;

    (* Manejo del botón de aborto *)
    IF btnAbort THEN
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        IF fase <> 5 THEN
            fase := 5;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA, nivelB, nivelVacio, btnInicio, btnAbort : BOOL;
    temp : REAL;
END_VAR

VAR_OUTPUT
    vA, vB, calentador, mezclador, vDescarga : BOOL;
    fase : INT;
END_VAR

VAR
    timerMezclador : TON;
    estado : INT := 0; // 0: reposo, 1: fase 1, 2: fase 2, 3: fase 3, 4: fase 4, 5: fase 5
END_VAR

METHOD StartBatch : VOID
    IF btnInicio AND estado = 0 THEN
        estado := 1;
    END_IF;
END_METHOD

METHOD AbortBatch : VOID
    IF btnAbort THEN
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;

        IF nivelVacio THEN
            estado := 0;
        ELSE
            estado := 5;
        END_IF;
    END_IF;
END_METHOD

METHOD UpdateBatch : VOID
    CASE estado OF
        0: // Reposo
            fase := 0;
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;

        1: // Fase 1: Dosificar componente A
            fase := 1;
            vA := TRUE;
            IF nivelA THEN
                vA := FALSE;
                estado := 2;
            END_IF;

        2: // Fase 2: Dosificar componente B
            fase := 2;
            vB := TRUE;
            IF nivelB THEN
                vB := FALSE;
                estado := 3;
            END_IF;

        3: // Fase 3: Calentar
            fase := 3;
            calentador := TRUE;
            IF temp >= 60.0 THEN
                calentador := FALSE;
                estado := 4;
            END_IF;

        4: // Fase 4: Mezclar
            fase := 4;
            mezclador := TRUE;
            timerMezclador(IN := TRUE, PT := T#120S);
            IF timerMezclador.Q THEN
                mezclador := FALSE;
                timerMezclador(IN := FALSE);
                estado := 5;
            END_IF;

        5: // Fase 5: Descargar
            fase := 5;
            vDescarga := TRUE;
            IF nivelVacio THEN
                vDescarga := FALSE;
                estado := 0;
            END_IF;
    END_CASE;
END_METHOD

METHOD Execute : VOID
    StartBatch();
    AbortBatch();
    UpdateBatch();
END_METHOD

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA, nivelB, nivelVacio, btnInicio, btnAbort : BOOL;
    temp : REAL;
END_VAR

VAR_OUTPUT
    vA, vB, calentador, mezclador, vDescarga : BOOL;
    fase : INT;
END_VAR

VAR
    timerMezclador : TON;
    estado : INT := 0; // 0: reposo, 1: dosificar A, 2: dosificar B, 3: calentar, 4: mezclar, 5: descargar
    timerMezcladorActive : BOOL := FALSE;
END_VAR

METHOD StartBatch : BOOL
    IF btnInicio AND estado = 0 THEN
        estado := 1;
        RETURN TRUE;
    END_IF
    RETURN FALSE;
END_METHOD

METHOD AbortBatch : BOOL
    IF btnAbort AND estado > 0 THEN
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        IF NOT nivelVacio THEN
            estado := 5;
        ELSE
            estado := 0;
        END_IF
        RETURN TRUE;
    END_IF
    RETURN FALSE;
END_METHOD

METHOD UpdateBatch : BOOL
    CASE estado OF
        0: // Reposo
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 0;
        1: // Dosificar A
            vA := TRUE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 1;
            IF nivelA THEN
                vA := FALSE;
                estado := 2;
            END_IF;
        2: // Dosificar B
            vA := FALSE;
            vB := TRUE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 2;
            IF nivelB THEN
                vB := FALSE;
                estado := 3;
            END_IF;
        3: // Calentar
            vA := FALSE;
            vB := FALSE;
            calentador := TRUE;
            mezclador := FALSE;
            vDescarga := FALSE;
            fase := 3;
            IF temp >= 60.0 THEN
                calentador := FALSE;
                estado := 4;
            END_IF;
        4: // Mezclar
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := TRUE;
            vDescarga := FALSE;
            fase := 4;
            IF NOT timerMezcladorActive THEN
                timerMezclador(IN := TRUE, PT := T#120S);
                timerMezcladorActive := TRUE;
            END_IF;
            IF timerMezclador.Q THEN
                mezclador := FALSE;
                timerMezcladorActive := FALSE;
                estado := 5;
            END_IF;
        5: // Descargar
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            vDescarga := TRUE;
            fase := 5;
            IF nivelVacio THEN
                vDescarga := FALSE;
                estado := 0;
            END_IF;
    END_CASE
    RETURN TRUE;
END_METHOD

METHOD Execute : BOOL
    IF AbortBatch() THEN
        RETURN TRUE;
    END_IF;
    IF StartBatch() THEN
        RETURN TRUE;
    END_IF;
    IF UpdateBatch() THEN
        RETURN TRUE;
    END_IF;
    RETURN FALSE;
END_METHOD

METHOD Reset : BOOL
    estado := 0;
    RETURN TRUE;
END_METHOD
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA     : BOOL; // Sensor de nivel alcanzado para componente A
    nivelB     : BOOL; // Sensor de nivel alcanzado para componente B
    nivelVacio : BOOL; // Sensor de reactor vacío
    btnInicio  : BOOL; // Botón para iniciar la receta
    btnAbort   : BOOL; // Botón para abortar el proceso
    temp       : REAL; // Temperatura actual del reactor
END_VAR

VAR_OUTPUT
    vA         : BOOL; // Válvula de dosificación componente A
    vB         : BOOL; // Válvula de dosificación componente B
    calentador : BOOL; // Actuador del calentador
    mezclador  : BOOL; // Actuador del mezclador
    vDescarga  : BOOL; // Válvula de descarga
    fase       : INT;  // Fase actual del proceso (0 a 5)
END_VAR

VAR
    TON_Mezcla : TON;  // Temporizador para la fase de mezclado
END_VAR

// ---------------------------------------------------------
// Lógica de Aborto
// ---------------------------------------------------------
IF btnAbort AND fase > 0 THEN
    IF fase <> 5 THEN
        IF NOT nivelVacio THEN
            fase := 5; // Si hay producto, pasar a descarga
        ELSE
            fase := 0; // Si está vacío, pasar a reposo
        END_IF;
    END_IF;
    // Si la fase ya es 5, el aborto no hace nada y continúa la descarga
END_IF;

// ---------------------------------------------------------
// Máquina de Estados (Receta)
// ---------------------------------------------------------
CASE fase OF
    0: // Fase 0: Reposo
        IF btnInicio THEN
            fase := 1;
        END_IF;

    1: // Fase 1: Dosificar componente A
        IF nivelA THEN
            fase := 2;
        END_IF;

    2: // Fase 2: Dosificar componente B
        IF nivelB THEN
            fase := 3;
        END_IF;

    3: // Fase 3: Calentar
        IF temp >= 60.0 THEN
            fase := 4;
        END_IF;

    4: // Fase 4: Mezclar
        IF TON_Mezcla.Q THEN
            fase := 5;
        END_IF;

    5: // Fase 5: Descargar
        IF nivelVacio THEN
            fase := 0;
        END_IF;
END_CASE;

// ---------------------------------------------------------
// Actualización de Temporizadores
// ---------------------------------------------------------
// El temporizador solo avanza cuando la fase activa es la 4
TON_Mezcla(IN := (fase = 4), PT := T#120S);

// ---------------------------------------------------------
// Asignación de Salidas
// ---------------------------------------------------------
// Las salidas se activan exclusivamente en su fase correspondiente.
// Un aborto cierra inmediatamente vA, vB, calentador y mezclador al cambiar la fase.
vA         := (fase = 1);
vB         := (fase = 2);
calentador := (fase = 3);
mezclador  := (fase = 4);
vDescarga  := (fase = 5);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA    : BOOL; (* Sensor nivel componente A alcanzado *)
    nivelB    : BOOL; (* Sensor nivel componente B alcanzado *)
    nivelVacio: BOOL; (* Sensor reactor vacio *)
    btnInicio : BOOL; (* Boton arranque receta *)
    btnAbort  : BOOL; (* Boton abortar receta *)
    temp      : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA        : BOOL; (* Valvula componente A *)
    vB        : BOOL; (* Valvula componente B *)
    calentador: BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Valvula de descarga *)
    fase      : INT;  (* Fase activa: 0=reposo, 1-5=receta *)
END_VAR
VAR
    tMezcla   : TON;  (* Temporizador mezcla 120 s *)
    abortando : BOOL; (* Indica que se esta ejecutando un abort *)
END_VAR

(* --- Logica de abort: activo en fases 1 a 5, ignorado en reposo --- *)
IF btnAbort AND (fase >= 1) AND (fase <= 5) THEN
    (* Detener inmediatamente actuadores excepto descarga *)
    vA         := FALSE;
    vB         := FALSE;
    calentador := FALSE;
    mezclador  := FALSE;
    abortando  := TRUE;

    IF fase <> 5 THEN
        (* Si hay producto en el reactor, ir a descarga *)
        IF NOT nivelVacio THEN
            fase := 5;
        ELSE
            (* Reactor ya vacio, volver a reposo *)
            fase      := 0;
            abortando := FALSE;
        END_IF;
    END_IF;
    (* Si ya estabamos en fase 5, continuamos la descarga normalmente *)
END_IF;

(* --- Maquina de estados secuencial --- *)
CASE fase OF

    0: (* Reposo *)
        (* Todos los actuadores apagados *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        abortando  := FALSE;
        tMezcla(IN := FALSE, PT := T#120S); (* Resetear temporizador *)

        (* Arranque solo desde reposo *)
        IF btnInicio THEN
            fase := 1;
        END_IF;

    1: (* Dosificar componente A *)
        vA         := TRUE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;

        IF nivelA THEN
            vA   := FALSE;
            fase := 2;
        END_IF;

    2: (* Dosificar componente B *)
        vA         := FALSE;
        vB         := TRUE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;

        IF nivelB THEN
            vB   := FALSE;
            fase := 3;
        END_IF;

    3: (* Calentar hasta 60.0 grados *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := TRUE;
        mezclador  := FALSE;
        vDescarga  := FALSE;

        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase       := 4;
        END_IF;

    4: (* Mezclar durante 120 segundos *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := TRUE;
        vDescarga  := FALSE;

        tMezcla(IN := TRUE, PT := T#120S);

        IF tMezcla.Q THEN
            mezclador := FALSE;
            tMezcla(IN := FALSE, PT := T#120S); (* Resetear para proximo ciclo *)
            fase := 5;
        END_IF;

    5: (* Descargar hasta reactor vacio *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := TRUE;

        IF nivelVacio THEN
            vDescarga := FALSE;
            fase      := 0;
            abortando := FALSE;
        END_IF;

    ELSE
        (* Estado desconocido: volver a reposo de forma segura *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        fase       := 0;
        abortando  := FALSE;

END_CASE;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL;      // Sensor de nivel para componente A
    nivelB : BOOL;      // Sensor de nivel para componente B
    nivelVacio : BOOL;  // Sensor de nivel para tanque vacío
    btnInicio : BOOL;   // Botón de inicio de la receta
    btnAbort : BOOL;    // Botón de aborto de la receta
    temp : REAL;        // Temperatura actual del reactor
END_VAR

VAR_OUTPUT
    vA : BOOL;          // Válvula para dosificar componente A
    vB : BOOL;          // Válvula para dosificar componente B
    calentador : BOOL;  // Calentador del reactor
    mezclador : BOOL;   // Mezclador del reactor
    vDescarga : BOOL;   // Válvula de descarga del reactor
    fase : INT;         // Fase actual del proceso
END_VAR

VAR
    timerMezcla : TON;  // Temporizador para la fase de mezcla
    recetaEnCurso : BOOL; // Indica si la receta está en curso
END_VAR

// Inicialización de variables
IF NOT recetaEnCurso THEN
    fase := 0;
END_IF

// Lógica de control por lotes
CASE fase OF
    0: // Reposo
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF btnInicio AND NOT recetaEnCurso THEN
            recetaEnCurso := TRUE;
            fase := 1;
        END_IF

    1: // Fase 1: Dosificación de A
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF

    2: // Fase 2: Dosificación de B
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF

    3: // Fase 3: Calentamiento
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF

    4: // Fase 4: Mezcla
        mezclador := TRUE;
        timerMezcla(IN := TRUE, PT := T#120S);
        IF timerMezcla.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF

    5: // Fase 5: Descarga
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            recetaEnCurso := FALSE;
            fase := 0;
        END_IF
END_CASE

// Lógica de aborto
IF btnAbort AND recetaEnCurso THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;

    IF NOT nivelVacio THEN
        fase := 5; // Ir a descarga si no está vacío
    ELSE
        recetaEnCurso := FALSE;
        fase := 0; // Ir a reposo si ya está vacío
    END_IF
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA    : BOOL; (* Sensor nivel componente A alcanzado *)
    nivelB    : BOOL; (* Sensor nivel componente B alcanzado *)
    nivelVacio: BOOL; (* Sensor reactor vacio *)
    btnInicio : BOOL; (* Boton arranque receta *)
    btnAbort  : BOOL; (* Boton abortar receta *)
    temp      : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA        : BOOL; (* Valvula componente A *)
    vB        : BOOL; (* Valvula componente B *)
    calentador: BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Valvula de descarga *)
    fase      : INT;  (* Fase activa: 0=reposo, 1-5=receta *)
END_VAR
VAR
    tMezcla   : TON;  (* Temporizador mezcla 120 s *)
    abortando : BOOL; (* Indica que se esta ejecutando un abort *)
END_VAR

(* ------------------------------------------------------------------ *)
(* Logica de abort: activo en fases 1-5, ignorado en reposo (fase 0)  *)
(* ------------------------------------------------------------------ *)
IF btnAbort AND (fase >= 1) AND (fase <= 5) THEN
    abortando := TRUE;
    (* Cierre inmediato de actuadores excepto vDescarga *)
    vA         := FALSE;
    vB         := FALSE;
    calentador := FALSE;
    mezclador  := FALSE;

    IF fase <> 5 THEN
        (* Si hay producto en el reactor, ir a descarga *)
        IF NOT nivelVacio THEN
            fase := 5;
        ELSE
            (* Reactor ya vacio, volver a reposo *)
            fase      := 0;
            abortando := FALSE;
        END_IF;
    END_IF;
    (* Si ya estabamos en fase 5, continuamos la descarga normalmente *)
END_IF;

(* ------------------------------------------------------------------ *)
(* Maquina de estados de la receta                                     *)
(* ------------------------------------------------------------------ *)
CASE fase OF

    (* ---- FASE 0: Reposo ------------------------------------------ *)
    0:
        (* Asegurar todas las salidas apagadas *)
        vA         := FALSE;
        vB         := FALSE;
        calentador := FALSE;
        mezclador  := FALSE;
        vDescarga  := FALSE;
        abortando  := FALSE;

        (* Arranque solo desde reposo y sin abort activo *)
        IF btnInicio THEN
            fase := 1;
        END_IF;

    (* ---- FASE 1: Dosificar componente A --------------------------- *)
    1:
        vA        := TRUE;
        vB        := FALSE;
        calentador:= FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF nivelA THEN
            vA   := FALSE;
            fase := 2;
        END_IF;

    (* ---- FASE 2: Dosificar componente B --------------------------- *)
    2:
        vA        := FALSE;
        vB        := TRUE;
        calentador:= FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF nivelB THEN
            vB   := FALSE;
            fase := 3;
        END_IF;

    (* ---- FASE 3: Calentar hasta 60 grados ------------------------- *)
    3:
        vA        := FALSE;
        vB        := FALSE;
        calentador:= TRUE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase       := 4;
        END_IF;

    (* ---- FASE 4: Mezclar 120 segundos ----------------------------- *)
    4:
        vA        := FALSE;
        vB        := FALSE;
        calentador:= FALSE;
        mezclador := TRUE;
        vDescarga := FALSE;

        (* Temporizador activo mientras estemos en fase 4 *)
        tMezcla(IN := (fase = 4), PT := T#120S);

        IF tMezcla.Q THEN
            mezclador := FALSE;
            fase      := 5;
        END_IF;

    (* ---- FASE 5: Descargar hasta reactor vacio -------------------- *)
    5:
        vA        := FALSE;
        vB        := FALSE;
        calentador:= FALSE;
        mezclador := FALSE;
        vDescarga := TRUE;

        IF nivelVacio THEN
            vDescarga := FALSE;
            fase      := 0; (* Volver a reposo (normal o tras abort) *)
            abortando := FALSE;
        END_IF;

    (* ---- Estado inesperado: volver a reposo seguro ---------------- *)
    ELSE:
        vA        := FALSE;
        vB        := FALSE;
        calentador:= FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;
        abortando := FALSE;
        fase      := 0;

END_CASE;

(* Resetear temporizador cuando no estamos en fase 4 *)
IF fase <> 4 THEN
    tMezcla(IN := FALSE, PT := T#120S);
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL;      (* Sensor de nivel del componente A *)
    nivelB : BOOL;      (* Sensor de nivel del componente B *)
    nivelVacio : BOOL;  (* Sensor de reactor vacío *)
    btnInicio : BOOL;   (* Botón para iniciar la receta *)
    btnAbort : BOOL;    (* Botón para abortar la receta *)
    temp : REAL;        (* Temperatura actual del reactor *)
END_VAR

VAR_OUTPUT
    vA : BOOL;          (* Válvula del componente A *)
    vB : BOOL;          (* Válvula del componente B *)
    calentador : BOOL;  (* Actuador del calentador *)
    mezclador : BOOL;   (* Actuador del mezclador *)
    vDescarga : BOOL;   (* Válvula de descarga *)
    fase : INT := 0;    (* Fase actual de la receta (0 a 5) *)
END_VAR

VAR
    timerMezcla : TON;  (* Temporizador para la fase de mezcla *)
END_VAR

(* Actualización del temporizador: se activa solo durante la fase 4 *)
timerMezcla(IN := (fase = 4), PT := T#120S);

(* Lógica de Aborto: activa en cualquier fase de 1 a 5 *)
IF btnAbort AND (fase >= 1) AND (fase <= 5) THEN
    IF NOT nivelVacio THEN
        fase := 5; (* Si hay producto, pasa a descargar *)
    ELSE
        fase := 0; (* Si ya está vacío, pasa a reposo directo *)
    END_IF;
END_IF;

(* Máquina de estados de la receta secuencial *)
CASE fase OF
    0: (* Fase 0: Reposo *)
        IF btnInicio THEN
            fase := 1;
        END_IF;

    1: (* Fase 1: Dosificar A *)
        IF nivelA THEN
            fase := 2;
        END_IF;

    2: (* Fase 2: Dosificar B *)
        IF nivelB THEN
            fase := 3;
        END_IF;

    3: (* Fase 3: Calentar *)
        IF temp >= 60.0 THEN
            fase := 4;
        END_IF;

    4: (* Fase 4: Mezclar *)
        IF timerMezcla.Q THEN
            fase := 5;
        END_IF;

    5: (* Fase 5: Descargar *)
        IF nivelVacio THEN
            fase := 0;
        END_IF;
ELSE
    (* Estado seguro en caso de valor fuera de rango *)
    fase := 0; 
END_CASE;

(* Control de salidas físicas basado en la fase activa *)
(* Al evaluar al final, un aborto cierra las válvulas y actuadores de inmediato *)
vA := (fase = 1);
vB := (fase = 2);
calentador := (fase = 3);
mezclador := (fase = 4);
vDescarga := (fase = 5);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Nivel del componente A alcanzado *)
    nivelB : BOOL; (* Nivel del componente B alcanzado *)
    nivelVacio : BOOL; (* Reactor vacio *)
    btnInicio : BOOL; (* Boton de inicio de receta *)
    btnAbort : BOOL; (* Boton de aborto de receta *)
    temp : REAL; (* Temperatura del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Valvula de componente A *)
    vB : BOOL; (* Valvula de componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Valvula de descarga *)
    fase : INT; (* Fase actual de la receta (0 a 5) *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador de mezclado *)
    trigInicio : R_TRIG; (* Flanco de subida para inicio *)
    trigAbort : R_TRIG; (* Flanco de subida para aborto *)
END_VAR

(* Deteccion de pulsaciones *)
trigInicio(CLK := btnInicio);
trigAbort(CLK := btnAbort);

(* Logica de aborto: activa en cualquier fase distinta de reposo *)
IF trigAbort.Q AND fase > 0 THEN
    IF NOT nivelVacio THEN
        fase := 5; (* Pasa a descarga si hay producto *)
    ELSE
        fase := 0; (* Vuelve a reposo si ya esta vacio *)
    END_IF;
END_IF;

(* Maquina de estados secuencial *)
CASE fase OF
    0: (* Fase 0: Reposo *)
        IF trigInicio.Q THEN
            fase := 1;
        END_IF;

    1: (* Fase 1: Dosificar componente A *)
        IF nivelA THEN
            fase := 2;
        END_IF;

    2: (* Fase 2: Dosificar componente B *)
        IF nivelB THEN
            fase := 3;
        END_IF;

    3: (* Fase 3: Calentar *)
        IF temp >= 60.0 THEN
            fase := 4;
        END_IF;

    4: (* Fase 4: Mezclar *)
        IF tMezcla.Q THEN
            fase := 5;
        END_IF;

    5: (* Fase 5: Descargar *)
        IF nivelVacio THEN
            fase := 0;
        END_IF;
END_CASE;

(* Control del temporizador de mezcla *)
tMezcla(IN := (fase = 4), PT := T#120S);

(* Control de salidas basado en la fase activa *)
vA := (fase = 1);
vB := (fase = 2);
calentador := (fase = 3);
mezclador := (fase = 4);
vDescarga := (fase = 5);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Nivel del componente A *)
    nivelB : BOOL; (* Nivel del componente B *)
    nivelVacio : BOOL; (* Nivel vacío del reactor *)
    btnInicio : BOOL; (* Botón de inicio *)
    btnAbort : BOOL; (* Botón de aborto *)
    temp : REAL; (* Temperatura del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula del componente A *)
    vB : BOOL; (* Válvula del componente B *)
    calentador : BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual *)
END_VAR
VAR
    tMezclar : TP; (* Temporizador para mezclar *)
    inicioPulsado : BOOL := FALSE; (* Estado del botón de inicio *)
    abortPulsado : BOOL := FALSE; (* Estado del botón de aborto *)
END_VAR

(* Manejo del botón de inicio *)
IF btnInicio AND NOT inicioPulsado AND fase = 0 THEN
    inicioPulsado := TRUE;
    fase := 1;
END_IF;

(* Manejo del botón de aborto *)
IF btnAbort AND NOT abortPulsado THEN
    abortPulsado := TRUE;
    CASE fase OF
        1..5:
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        5:
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
    END_CASE;
END_IF;

(* Fase 1: Dosificar el componente A *)
IF fase = 1 THEN
    vA := TRUE;
    IF nivelA THEN
        vA := FALSE;
        fase := 2;
    END_IF;
END_IF;

(* Fase 2: Dosificar el componente B *)
IF fase = 2 THEN
    vB := TRUE;
    IF nivelB THEN
        vB := FALSE;
        fase := 3;
    END_IF;
END_IF;

(* Fase 3: Calentar *)
IF fase = 3 THEN
    calentador := TRUE;
    IF temp >= 60.0 THEN
        calentador := FALSE;
        fase := 4;
    END_IF;
END_IF;

(* Fase 4: Mezclar *)
IF fase = 4 THEN
    mezclador := TRUE;
    tMezclar(IN := TRUE, PT := T#120S);
    IF tMezclar.Q THEN
        mezclador := FALSE;
        fase := 5;
    END_IF;
END_IF;

(* Fase 5: Descargar *)
IF fase = 5 THEN
    vDescarga := TRUE;
    IF nivelVacio THEN
        vDescarga := FALSE;
        fase := 0;
    END_IF;
END_IF;

(* Reinicio de los botones *)
IF NOT btnInicio THEN
    inicioPulsado := FALSE;
END_IF;
IF NOT btnAbort THEN
    abortPulsado := FALSE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
