END_IF;

(* Maquina de estados de la receta *)
CASE fase OF
    0: (* Fase 0: Reposo *)
        IF btnInicio THEN
            fase := 1;
        END_IF;

    1: (* Fase 1: Dosificar componente A *)
        IF nivelA THEN
            fase := 2;
        END_IF;

    2: (* Fase 2: Dosificar componente B *)
        IF nivelB THEN
            fase := 3;
        END_IF;

    3: (* Fase 3: Calentar *)
        IF temp >= 60.0 THEN
            fase := 4;
        END_IF;

    4: (* Fase 4: Mezclar *)
        IF tMezcla.Q THEN
            fase := 5;
        END_IF;

    5: (* Fase 5: Descargar *)
        IF nivelVacio THEN
            fase := 0;
        END_IF;
ELSE
    fase := 0; (* Seguridad: estado no definido vuelve a reposo *)
END_CASE;

(* Temporizador de mezcla: activo solo durante la fase 4 *)
tMezcla(IN := (fase = 4), PT := T#120S);

(* Asignacion de salidas segun la fase activa *)
vA := (fase = 1);
vB := (fase = 2);
calentador := (fase = 3);
mezclador := (fase = 4);
vDescarga := (fase = 5);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL;       // Sensor de nivel para el componente A
    nivelB : BOOL;       // Sensor de nivel para el componente B
    nivelVacio : BOOL;   // Sensor de nivel para el estado vacío
    btnInicio : BOOL;    // Botón de inicio
    btnAbort : BOOL;     // Botón de aborto
    temp : REAL;         // Temperatura actual del reactor
END_VAR

VAR_OUTPUT
    vA : BOOL;           // Válvula para dosificar componente A
    vB : BOOL;           // Válvula para dosificar componente B
    calentador : BOOL;   // Calentador del reactor
    mezclador : BOOL;    // Mezclador del reactor
    vDescarga : BOOL;    // Válvula de descarga
    fase : INT;          // Fase actual del proceso
END_VAR

VAR
    timerMezcla : TON;   // Temporizador para la fase de mezcla
    inicioPrev : BOOL;   // Estado previo del botón de inicio
    abortPrev : BOOL;    // Estado previo del botón de aborto
END_VAR

// Inicialización
IF NOT btnInicio THEN
    inicioPrev := FALSE;
END_IF

IF NOT btnAbort THEN
    abortPrev := FALSE;
END_IF

// Control de fases
CASE fase OF
    0: // Reposo
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;

        IF btnInicio AND NOT inicioPrev THEN
            fase := 1;
        END_IF

    1: // Fase 1: Dosificación de A
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF

    2: // Fase 2: Dosificación de B
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF

    3: // Fase 3: Calentamiento
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF

    4: // Fase 4: Mezcla
        mezclador := TRUE;
        timerMezcla(IN := TRUE, PT := T#120S);
        IF timerMezcla.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF

    5: // Fase 5: Descarga
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            fase := 0;
        END_IF
END_CASE

// Manejo del botón de aborto
IF btnAbort AND NOT abortPrev THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;

    IF NOT nivelVacio THEN
        fase := 5;
    ELSE
        fase := 0;
    END_IF
END_IF

// Actualización de estados previos
inicioPrev := btnInicio;
abortPrev := btnAbort;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL;
    nivelB : BOOL;
    nivelVacio : BOOL;
    btnInicio : BOOL;
    btnAbort : BOOL;
    temp : REAL;
END_VAR

VAR_OUTPUT
    vA : BOOL;
    vB : BOOL;
    calentador : BOOL;
    mezclador : BOOL;
    vDescarga : BOOL;
    fase : INT := 0;
END_VAR

VAR
    timerMezcla : TON;
    trigInicio : R_TRIG;
    trigAbort : R_TRIG;
END_VAR

// Detección de flancos para los botones
trigInicio(CLK := btnInicio);
trigAbort(CLK := btnAbort);

// Lógica de Aborto (ignorado en reposo, fase = 0)
IF trigAbort.Q AND fase > 0 THEN
    IF NOT nivelVacio THEN
        fase := 5; // Pasa a descarga si hay producto en el reactor
    ELSE
        fase := 0; // Vuelve a reposo directo si ya está vacío
    END_IF;
END_IF;

// Máquina de estados secuencial
CASE fase OF
    0: // Fase 0: Reposo
        IF trigInicio.Q THEN
            fase := 1;
        END_IF;

    1: // Fase 1: Dosificar componente A
        IF nivelA THEN
            fase := 2;
        END_IF;

    2: // Fase 2: Dosificar componente B
        IF nivelB THEN
            fase := 3;
        END_IF;

    3: // Fase 3: Calentar
        IF temp >= 60.0 THEN
            fase := 4;
        END_IF;

    4: // Fase 4: Mezclar
        IF timerMezcla.Q THEN
            fase := 5;
        END_IF;

    5: // Fase 5: Descargar
        IF nivelVacio THEN
            fase := 0;
        END_IF;
END_CASE;

// Temporizador de mezcla (se activa únicamente durante la fase 4)
timerMezcla(IN := (fase = 4), PT := T#120S);

// Asignación de salidas (se cierran/apagan automáticamente al cambiar de fase)
vA := (fase = 1);
vB := (fase = 2);
calentador := (fase = 3);
mezclador := (fase = 4);
vDescarga := (fase = 5);

END_FUNCTION_BLOCK
